window.__ZHIYIN_IDS__ = {"en": {"dissonance": "DUHtkEpkcU3mSoSZ", "tremor": "EZqDfFz42z6IVq0Q", "drag": "28J3SSb57CaBUp06", "offkey": "f9YClSDb3zYtBFGA", "quaver": "PkbQLCeTeNB7kKeQ", "snare": "RUqRt9h1Ot5T2WK3", "muffle": "P7dN6Sy5YJ427kIQ", "silentbeat": "3h4kKbskEj1fgqiK", "crack": "SlN1LTUoOQKeAv6Z", "stumble": "JIlLIYbD3g8wz103"}, "al": {"inspire": "5GIGic13hWr38Rz3", "crescendo": "FHzIjFZ2Ea54ALck", "sanctuary": "pheYfy1g5G7pSgl6", "distract": "tUaYOONmvev4MHR3", "concerto": "zwCBfe19uipQJuJA", "glissando": "E0byhS8qUxZdAuAw", "rondo": "piHfCYnPrZXxl6KN", "reprise": "mOIFbJnpDMoRqJfw", "sustain": "FRZg9pSODSQDhTI0", "fugue": "lyVkb7PfdjzXob6z"}, "eneff": {"dissonance": "bO2UjppRA3AucAKc", "tremor": "dMcbgnpyo9hOnP8l", "drag": "Glj0518Y7hyxuyqB", "offkey": "GIknr37uXTUlXyY1", "quaver": "JApmpGv7fz8l4cHX", "snare": "js1cPuC0U9AtLxDM", "muffle": "ccGIj4DLyV6rgL1j", "silentbeat": "Qau3XuzcadJrB63q", "crack": "iqKvi6TpydROfZ3O", "stumble": "eOQB1LpKxlkInYYt"}, "aleff": {"inspire": "3wTJ39mOu9RLcyjX", "crescendo": "gs0pDiRcgiy7rqzG", "sanctuary": "ZOIQlFkIdFAMjv6G", "distract": "5mJxNYrBzC4ppcXE", "concerto": "Zujr0fzAd1f0SRd6", "glissando": "b8v5eJLiLCbQ7loz", "rondo": "Dx0UChxGQ51r912V", "reprise": "cAuAAmNDeKtNFoZi", "sustain": "cTB47LmoTd5RG51A", "fugue": "CkEnTrcYYxRxTp0Z"}, "req_en": "c1jbmxl2b49HHuoU", "req_al": "6dP0vQi6jDsczkoJ", "panel": "DI1WSGQTE1bOWKaA"};
window.__ZHIYIN_NOTES__ = {"en": {"dissonance": {"name": "不谐  Dissonance", "official": "在该效果持续期间，目标进行的每一次豁免检定都减去 1d4。持续 1 分钟。"}, "tremor": {"name": "颤音  Tremor", "official": "目标的轮廓在震颤中暴露：针对目标的攻击检定具有优势，直到其下一回合结束。"}, "drag": {"name": "滞音  Drag", "official": "目标的速度减半，且目标的敏捷豁免检定具有劣势，直到其下一回合结束。"}, "offkey": {"name": "走音  Off-Key", "official": "目标的下一次攻击检定具有劣势。"}, "quaver": {"name": "怯音  Quaver", "official": "目标须进行一次感知豁免检定。若失败，目标陷入恐慌状态，并以你为恐惧源，直到其下一回合结束。"}, "snare": {"name": "绊音  Snare", "official": "目标须进行一次力量豁免检定。若失败，目标陷入束缚状态，直到其下一回合结束。"}, "muffle": {"name": "失聪  Muffle", "official": "目标须进行一次体质豁免检定。若失败，目标陷入失聪状态，且无法施展具有言语（V）成分的法术，直到其下一回合结束。"}, "silentbeat": {"name": "静拍  Silent Beat", "official": "目标无法做出反应，直到其下一回合结束。"}, "crack": {"name": "裂音  Crack", "official": "目标对雷鸣伤害与力场伤害易伤，直到其下一回合结束。"}, "stumble": {"name": "乱拍  Stumble", "official": "目标的下一次豁免检定具有劣势。"}}, "al": {"inspire": {"name": "激励  Inspiration", "official": "目标获得一枚知音激励骰（1d8）。在接下来的 10 分钟内，当目标进行一次属性检定、攻击检定或豁免检定时，可以掷动该骰，并将掷出的结果加到该次检定上；目标可在掷出 d20 之后、但在 DM 宣布结果之前决定是否使用该骰。该骰用后即耗。"}, "crescendo": {"name": "强音和弦  Resonant Crescendo", "official": "目标下一次以攻击或法术造成伤害时，对该次伤害追加雷鸣伤害，其数值等同于你的吟游诗人等级；若被造成伤害的目标当前处于失谐状态（带有知音的任一敌弦效果），则该追加伤害翻倍。此效果在目标造成一次伤害后结束。"}, "sanctuary": {"name": "庇护和弦  Chord of Sanctuary", "official": "目标的下一次豁免检定获得加值，其数值等同于你的魅力调整值。"}, "distract": {"name": "扰敌和弦  Chord of Distraction", "official": "一层惑人的微光环绕目标。针对它的下一次攻击检定具有劣势。"}, "concerto": {"name": "协奏  Concerto", "official": "目标的下一次攻击检定具有优势。"}, "glissando": {"name": "滑音  Glissando", "official": "直到其下一回合结束，当目标受到一次攻击时（无论命中与否），它可以使用其反应瞬移至 15 尺内一处它能看见且未被占据的空间；此次移动不会引发借机攻击。"}, "rondo": {"name": "回旋  Rondo", "official": "目标的速度提高 15 尺，且目标的敏捷豁免检定具有优势，直到其下一回合结束。"}, "reprise": {"name": "复奏  Reprise", "official": "目标获得临时生命值，其数值等同于你的魅力调整值加上你的吟游诗人等级。"}, "sustain": {"name": "延音  Sustain", "official": "目标在用于维持专注的体质豁免检定上具有优势，直到其下一回合结束。"}, "fugue": {"name": "赋格  Fugue", "official": "直到其下一回合结束，当目标以一次攻击击中你的一个失谐目标时，你回复生命值，其数值等同于你的魅力调整值。"}}, "req": {"en": "每个敌人须进行一次魅力豁免检定。若失败，该敌人对你陷入恐慌状态、且速度减半，直到其下一回合结束。", "al": "你与每个盟友各获得临时生命值，其数值等同于你的魅力调整值加上你的吟游诗人等级。"}};
// ============================================================
// 知音 · 和鸣  The Confidant, Reforged — 物品宏 [postActiveEffects]
// 指挥之臂（额外附赠动作）演奏知音：消耗诗人激励，奏出和弦。
// 对敌/对盟友效应经隐藏活动 completeActivityUse 走 midi（自动 GM 权限）。
// ============================================================
(async () => {
  const IDS = window.__ZHIYIN_IDS__;
  const NOTES = window.__ZHIYIN_NOTES__;
  const actor = (typeof item !== "undefined" && item?.actor) ? item.actor
              : (typeof token !== "undefined" && token?.actor) ? token.actor
              : game.user?.character;
  const theItem = (typeof item !== "undefined" && item) ? item : null;
  if (!actor || !theItem) { ui.notifications.warn("知音：找不到持有者或物品。"); return; }

  // 递归守卫：子活动会重跑本宏，只有「演奏知音」开面板
  try {
    const an = (typeof workflow !== "undefined" && workflow?.activity?.name) ? workflow.activity.name : "";
    if (an && !an.includes("演奏知音")) return;
  } catch (e) {}
  if (globalThis.__zhiyinPanelOpen) return;

  const DV2 = foundry.applications.api.DialogV2;
  const bardlvl = actor.classes?.bard?.system?.levels
    ?? actor.itemTypes.class.find(c => (c.identifier || c.system?.identifier) === "bard")?.system?.levels ?? 7;
  const chamod = actor.system.abilities.cha.mod;
  const EN_KEYS = Object.keys(NOTES.en), AL_KEYS = Object.keys(NOTES.al);
  const rand = a => a[Math.floor(Math.random() * a.length)];
  const nm = (side, k) => NOTES[side][k].name.split("  ")[0];          // 中文名
  const ofc = (side, k) => NOTES[side][k].official;                    // 官方全文
  const opt = (keys, side) => keys.map(k =>
    `<option value="${k}">${nm(side, k)} — ${ofc(side, k)}</option>`).join("");

  // —— 面板白色/两排/可调：DialogV2 会清洗 content 内样式，CSS 注入到 document.head ——
  function injectCSS() {
    if (document.getElementById("zhiyin-style")) return;
    const st = document.createElement("style"); st.id = "zhiyin-style";
    st.textContent = `
      .zhiyin-dlg .window-content{ background:#ffffff !important; color:#23201b !important; }
      .zhiyin-dlg .window-header{ background:#f3eddf !important; color:#3a2c12 !important; }
      .zhiyin-dlg .dialog-content, .zhiyin-dlg p, .zhiyin-dlg label{ color:#23201b !important; }
      /* 两排：v13 DialogV2 页脚按钮容器各种可能的类名都覆盖 */
      .zhiyin-dlg .dialog-buttons,
      .zhiyin-dlg menu.dialog-buttons,
      .zhiyin-dlg .form-footer,
      .zhiyin-dlg footer.form-footer,
      .zhiyin-dlg .window-content > menu,
      .zhiyin-dlg .window-content > footer{
        display:grid !important; grid-template-columns:repeat(3,1fr) !important;
        gap:6px !important; width:100%; }
      .zhiyin-dlg button{ background:#ffffff !important; color:#3a2c12 !important;
        border:1px solid #c9b070 !important; border-radius:6px !important; min-height:36px; flex:none !important; }
      .zhiyin-dlg button:hover{ background:#f6efda !important; box-shadow:0 0 4px #c9b070; }
      .zhiyin-dlg select, .zhiyin-dlg option{ background:#ffffff !important; color:#23201b !important;
        border:1px solid #c9b070 !important; padding:3px; }
      .zhiyin-dlg .zybind{ grid-template-columns:1fr 1fr !important; }
    `;
    document.head.appendChild(st);
  }
  const removeCSS = () => document.getElementById("zhiyin-style")?.remove();
  const DLG = { classes: ["zhiyin-dlg"], window: { resizable: true } };

  // —— 激励：可绑定（存物品 flag），否则按名查找 ——
  function findInsp() {
    const bid = theItem.getFlag("world", "zhiyinInspId");
    if (bid) { const b = actor.items.get(bid); if (b) return b; }
    const m = actor.items.filter(i => {
      const n = i.name || "";
      if (/魔法激励|magical\s*inspiration/i.test(n)) return false;   // 6级特性，不是激励计数源
      return ["诗人激励","吟游激励","Bardic Inspiration"].some(x => n.includes(x)) ||
             (i.system?.identifier || "") === "bardic-inspiration";
    });
    return m.find(i => i.system?.uses?.max) || m[0] || null;   // 优先真正带次数的那个
  }
  function inspRemaining(it) {
    const u = it?.system?.uses || {};
    if (u.value != null && u.value !== "") { const v = Number(u.value); if (!Number.isNaN(v)) return v; }
    if (u.max != null && u.max !== "") { const mx = Number(u.max); if (!Number.isNaN(mx)) return mx - (u.spent||0); }
    return NaN; // 次数无法判定（如绑到没配次数的特性）
  }
  async function spend(n) {
    const it = findInsp();
    if (!it) return DV2.confirm({ ...DLG, window:{title:"知音"},
      content:`<p>未找到吟游诗人激励特性。请先用面板的「⚙ 绑定激励骰」选定它（注意选有次数的那个，不是「魔法激励」）。是否仍要演奏？（请手动扣 ${n} 次）</p>` });
    const rem = inspRemaining(it);
    if (Number.isNaN(rem)) return DV2.confirm({ ...DLG, window:{title:"知音"},
      content:`<p>「${it.name}」没有可读的激励次数（可能绑错了特性）。是否仍要演奏？（请手动扣 ${n} 次）</p>` });
    if (rem < n) { ui.notifications.warn(`知音：激励不足（需 ${n}，余 ${rem}）。`); return false; }
    await it.update({ "system.uses.spent": (it.system.uses.spent||0) + n }); return true;
  }
  async function bindInspiration() {
    const cands = actor.items.filter(i => i.type === "feat" || (i.system?.uses && (i.system.uses.max||i.system.uses.value!=null)));
    if (!cands.length) { ui.notifications.warn("知音：未找到任何带次数的特性。"); return; }
    const sel = await DV2.wait({
      ...DLG, window:{ title:"绑定激励骰", resizable:true },
      content:`<p>选择你卡上用作「诗人激励」的特性（演奏将从它扣次数）：</p>
        <select name="it" style="width:100%">${cands.map(i=>`<option value="${i.id}">${i.name}${i.system?.uses?.max?`（${inspRemaining(i)}/${i.system.uses.max}）`:""}</option>`).join("")}</select>`,
      buttons:[{action:"ok",label:"绑定",default:true,callback:(e,b)=>b.form.elements.it.value},{action:"cancel",label:"取消"}],
      rejectClose:false
    });
    if (sel && sel !== "cancel") {
      await theItem.setFlag("world","zhiyinInspId", sel);
      ui.notifications.info("知音：已绑定 " + (actor.items.get(sel)?.name || sel));
    }
  }

  // —— 透支借音：免动作借 1 枚激励，叠 1 层【失谐·债】（每层法术豁免 DC −1）；战斗外透支当场结算 ——
  const DEBT_NAME = "失谐·债 Dissonant Debt";
  function debtLayers() { return actor.appliedEffects.filter(e => e.name === DEBT_NAME).length; }
  async function overdraft() {
    const cur = debtLayers();
    if (cur >= chamod) { ui.notifications.warn("知音：你的心已经太乱了，这一拍，弹不出来。"); return; }
    const it = findInsp();
    if (it) { try { await it.update({ "system.uses.spent": Math.max(0, (it.system.uses.spent || 0) - 1) }); } catch (e) {} }
    else ui.notifications.info("知音：未绑定激励特性，已叠债，请手动 +1 枚激励。");
    const debt = {
      name: DEBT_NAME, img: "icons/magic/death/hand-withered-gray.webp",
      changes: [{ key: "system.bonuses.spell.dc", mode: 2, value: "-1", priority: 20 }],
      disabled: false, duration: {}, statuses: [],
      description: `<p>你向知音借了一段尚未结清的和弦。每层【失谐·债】使你所有法术的豁免难度 −1。这些不谐之音在战斗中被演奏托住；当战斗结束、或你在战斗之外透支时，每层对你造成等同于你诗人等级的心灵伤害，随后清零。</p>`,
      flags: { dae: { stackable: "multi", showIcon: true, specialDuration: [] }, world: { zhiyinDebt: true } },
    };
    await actor.createEmbeddedDocuments("ActiveEffect", [debt]);
    animate("透支借音");
    if (!game.combat?.started) {
      const dmg = bardlvl;
      try { await actor.applyDamage([{ value: dmg, type: "psychic" }]); }
      catch (e) { try { await actor.applyDamage(dmg); } catch (_) {} }
      const last = actor.effects.find(e => e.name === DEBT_NAME);
      if (last) await last.delete();
      ui.notifications.info(`知音：战斗外透支——尚无旋律托住，当场结算 ${dmg} 点心灵伤害。`);
    } else {
      ui.notifications.info(`知音：透支 +1 激励（失谐·债 ${cur + 1}/${chamod} 层，法术豁免 DC −${cur + 1}；战斗结束清算）。`);
    }
  }

  // —— v13 安全的设/清目标（你的 v13 没有 game.user.updateTokenTargets）——
  function clearTargets() {
    try { for (const t of [...(game.user.targets || [])]) t.setTarget?.(false, { user: game.user, releaseOthers: false }); } catch (e) {}
  }
  function setTargets(tokens) {
    try {
      clearTargets();
      for (const t of tokens) t?.setTarget?.(true, { user: game.user, releaseOthers: false });
    } catch (e) { console.warn("知音 setTargets:", e); }
  }

  async function fire(activityId, opts = {}) {
    const act = theItem.system.activities.get(activityId);
    if (!act) { ui.notifications.warn("知音：缺活动 " + activityId); return null; }
    return await MidiQOL.completeActivityUse(act, opts, {}, {});
  }
  // —— 滑音：给盟友临时挂一个 CPR genericTeleport 反应特性（受击瞬移15尺），照抄你"闪现晶"的验证配置 ——
  function glissandoFeat() {
    const actId = foundry.utils.randomID(16);
    const effId = foundry.utils.randomID(16);
    return {
      name: "滑音·闪身 Glissando",
      type: "feat",
      img: "icons/magic/control/buff-flight-wings-blue.webp",
      system: {
        description: { value: "<p>当你受到一次攻击时（无论命中与否），你可以用反应瞬移至 15 尺内你能看见的未占据空位，且此移动不引发借机攻击。</p>", chat: "" },
        uses: { spent: 0, max: "1", recovery: [{ period: "turn", type: "recoverAll" }] },
        type: { value: "", subtype: "" },
        activities: { [actId]: {
          type: "utility", _id: actId, sort: 100000,
          activation: { type: "reaction", value: null, override: false, condition: "" },
          consumption: { scaling: { allowed: false }, spellSlot: false, targets: [{ type: "itemUses", value: "1", target: "", scaling: {} }] },
          description: { chatFlavor: "" },
          duration: { units: "inst", concentration: false, override: false },
          effects: [{ _id: effId }],
          range: { override: false, units: "self", special: "" },
          target: { template: { contiguous: false, units: "ft", type: "", size: "", stationary: false }, affects: { choice: false, type: "self", count: "", special: "" }, override: false, prompt: true },
          uses: { spent: 0, recovery: [], max: "" },
          name: "闪身 Slip",
          useConditionText: "", useConditionReason: "", effectConditionText: "",
          midiProperties: { ignoreTraits: [], triggeredActivityId: "none", triggeredActivityConditionText: "", triggeredActivityTargets: "targets", triggeredActivityRollAs: "self", triggeredActivityConsume: true, triggeredActivityConfigure: true, autoConsume: false, forceConsumeDialog: "default", forceRollDialog: "default", forceDamageDialog: "default", confirmTargets: "default", autoTargetType: "any", autoTargetAction: "default", automationOnly: false, otherActivityCompatible: true, otherActivityAsParentType: true, identifier: "", displayActivityName: false, rollMode: "default", chooseEffects: false, toggleEffect: false, ignoreFullCover: false, removeChatButtons: "default", magicEffect: false, magicDamage: false, noConcentrationCheck: false, skipConcentrationCheck: false, autoCEEffects: "default" },
          img: null, flags: {},
          visibility: { level: {}, requireAttunement: false, requireIdentification: false, requireMagic: false },
          macroData: { name: "", command: "" },
          ignoreTraits: { idi: false, idr: false, idv: false, ida: false, idm: false },
          isOverTimeFlag: false,
          overTimeProperties: { saveRemoves: true, rollAs: "target", preRemoveConditionText: "", postRemoveConditionText: "" }
        } },
        identifier: "-glissando-slip",
        source: { revision: 1, rules: "2014" },
        properties: []
      },
      effects: [{
        _id: effId,
        name: "滑身 Glissando",
        img: "icons/magic/control/buff-flight-wings-blue.webp",
        type: "base",
        changes: [{ key: "flags.world.zhiyinSlipped", mode: 5, value: "1", priority: 20 }],
        disabled: false, transfer: false,
        duration: { rounds: 1, seconds: 6 },
        description: "<p>你刚借滑音闪身一步。</p>",
        statuses: [], flags: {}
      }],
      flags: {
        world: { zhiyinGlissando: true },
        dnd5e: { riders: { activity: [] } },
        "chris-premades": { config: { generic: { genericTeleport: { applied: true, activities: [actId], range: 15, animation: "mistyStep" } } },
                            macros: { midi: { item: ["genericTeleport"] } } }
      }
    };
  }
  async function grantGlissando(allyToken) {
    const feat = glissandoFeat();
    const tdoc = allyToken?.document ?? allyToken;            // Token→TokenDocument 兼容
    const tactor = tdoc?.actor ?? allyToken?.actor;
    const uuid = tdoc?.uuid;
    if (!tactor || !uuid) { ui.notifications.warn("知音：滑音找不到目标，反应未挂载。"); return; }
    let done = false;
    const myId = actor.id;
    // 直接删（owner 路径）/ socket 删（无权限路径）
    const localDelete = async () => { try { const ids = tactor.items.filter(i => i.name === feat.name).map(i => i.id); if (ids.length) await tactor.deleteEmbeddedDocuments("Item", ids); } catch (e) {} };
    const socketDelete = () => { try { game.socket.emit("module.world-scripter", { scope: "zhiyin", action: "revertItem", tokenUuid: uuid, itemName: feat.name }); } catch (e) {} };
    const makeRevert = (useLocal) => () => {
      if (done) return; done = true;
      if (useLocal) localDelete(); else { socketDelete(); if (game.user.isGM) localDelete(); }
    };
    // 回收时机：必须「先轮到别人、再轮回你」才撤——否则你正是在自己回合演奏，会当场把刚建的特性秒删
    const armRevert = (rev) => {
      let armed = false;
      const onTurn = () => {
        const cur = game.combat?.combatant?.actor?.id;
        if (cur && cur !== myId) { armed = true; return; }     // 轮到别人 → 武装
        if (cur === myId && armed) { Hooks.off("combatTurnChange", onTurn); Hooks.off("updateCombat", onTurn); rev(); }  // 再次轮到我 → 撤
      };
      Hooks.on("combatTurnChange", onTurn);
      Hooks.on("updateCombat", onTurn);
      Hooks.once("deleteCombat", () => { Hooks.off("combatTurnChange", onTurn); Hooks.off("updateCombat", onTurn); rev(); });
      // 不在战斗中不立即撤（非战斗下反应本就用不上，留着无害）
    };
    console.log("知音｜滑音发放：目标=", tactor?.name, "| 我是GM=", game.user.isGM, "| 对其owner=", tactor?.isOwner, "| 战斗已开始=", !!game.combat?.started);

    // 0) 我对该盟友有 owner 权限 → 直接建（最稳，不依赖 socket）
    try {
      if (tactor.isOwner) {
        if (!tactor.items.some(i => i.name === feat.name)) await tactor.createEmbeddedDocuments("Item", [feat]);
        const ok = tactor.items.find(i => i.name === feat.name);
        const cpr = !!ok?.flags?.["chris-premades"]?.config?.generic?.genericTeleport?.applied;
        armRevert(makeRevert(true));
        ui.notifications.info(`知音：滑音已直接挂到 ${tactor.name}（特性存在=${!!ok}，CPR瞬移=${cpr}）。受击时弹反应。`);
        console.log("知音｜滑音 直接建完成：", { 特性存在: !!ok, CPR瞬移已配: cpr, id: ok?.id });
        return;
      }
    } catch (e) { console.warn("知音 滑音 直接建失败：", e); ui.notifications.error("知音：滑音直接建失败，详见 F12（已转 socket 尝试）。"); }

    // 1) 无权限 → 原生 socket，由 world-scripter 的 GM 端建
    try {
      if (game.modules.get("world-scripter")?.active) {
        game.socket.emit("module.world-scripter", { scope: "zhiyin", action: "grantItem", tokenUuid: uuid, itemData: feat });
        armRevert(makeRevert(false));
        ui.notifications.info(`知音：已请 GM 给 ${tactor.name} 挂滑音（走 socket）。若没出现，多半是 world-scripter 的 socket 段没装/没重载。`);
        return;
      }
    } catch (e) { console.warn("知音 滑音 socket 失败：", e); }

    // 2) 兜底 warpgate
    try {
      if (typeof warpgate !== "undefined") {
        const mut = "zhiyin-gliss-" + (tdoc.id ?? allyToken.id);
        await warpgate.mutate(tdoc, { embedded: { Item: { [feat.name]: feat } } }, {}, { name: mut, comparisonKeys: { Item: "name" } });
        armRevert(() => { if (done) return; done = true; try { warpgate.revert(tdoc, mut); } catch (e) {} });
        return;
      }
    } catch (e) { console.warn("知音 滑音 warpgate 失败：", e); }

    ui.notifications.warn("知音：滑音反应未能自动挂载（请确认已装 world-scripter 的 socket 段，或你对该盟友有控制权）。本次按卡面手动：受击时反应瞬移 15 尺、不引借机。");
  }
  // 临时把占位符/数值改实数，派发后还原；improv 额外 +1 轮
  async function firePatched(activityId, effId, patches, bumpRound = false) {
    const eff = theItem.effects.get(effId);
    let origCh = null, origDur = null;
    if (eff) {
      origCh = foundry.utils.deepClone(eff.changes);
      const ch = foundry.utils.deepClone(eff.changes);
      for (const c of ch) for (const [f, r] of patches)
        if (typeof c.value === "string" && c.value.includes(f)) c.value = c.value.replaceAll(f, r);
      const upd = { changes: ch };
      if (bumpRound) { origDur = foundry.utils.deepClone(eff.duration);
        upd.duration = foundry.utils.mergeObject(foundry.utils.deepClone(eff.duration), { rounds: (eff.duration?.rounds||1)+1 }); }
      await eff.update(upd);
    }
    try { await fire(activityId); }
    finally { if (eff) { const back={changes:origCh}; if(origDur) back.duration=origDur; await eff.update(back); } }
  }
  // 单次型音符（到下次攻击/豁免/受击就结束）——续奏/即兴时改成整轮，避免"就一次"太飘
  const SINGLE = { al: ["concerto","sanctuary","distract"], en: ["offkey","stumble"] };
  // 统一演奏：side=al/en，opts={improv, rounds, clearSpecial, targetUuids}
  async function play(side, key, opts = {}) {
    const { improv = false, rounds = null, clearSpecial = false, targetUuids = null } = opts;
    const aid = (side === "al" ? IDS.al : IDS.en)[key];
    const eid = (side === "al" ? IDS.aleff : IDS.eneff)[key];
    const eff = theItem.effects.get(eid);
    const ex = improv ? chamod : 0;
    // 占位符 + 即兴数值 +魅力调整
    const patches = [];
    if (key === "crescendo") patches.push(["ZZBARDLVL", String(bardlvl + ex)]);
    else if (key === "sanctuary") patches.push(["ZZCHAMOD", String(chamod + ex)]);
    else if (improv && eff) {
      const num = eff.changes.find(c => /^[+\-]?\d+$/.test(String(c.value)));
      if (num) patches.push([String(num.value), String(Number(num.value) + (Number(num.value) < 0 ? -ex : ex))]);
    }
    // 轮型音符 = 持续到下回合（turnEnd）的那类，可延长；单次型保持"下一次"原样
    const isRound = (eff?.flags?.dae?.specialDuration ?? []).includes("turnEnd");
    let rr = rounds, cs = clearSpecial;
    if (improv && isRound) { rr = 2; cs = true; }   // 即兴只把轮型 +1 轮（到 2 轮）；单次型不动，避免变强且与卡面一致
    let backup = null;
    if (eff && (patches.length || rr != null || cs)) {
      backup = { changes: foundry.utils.deepClone(eff.changes),
                 duration: foundry.utils.deepClone(eff.duration),
                 special: foundry.utils.deepClone(eff.flags?.dae?.specialDuration ?? []) };
      const ch = foundry.utils.deepClone(eff.changes);
      for (const c of ch) for (const [f, r] of patches)
        if (typeof c.value === "string" && c.value.includes(f)) c.value = c.value.replaceAll(f, r);
      const upd = { changes: ch };
      if (rr != null) upd.duration = foundry.utils.mergeObject(foundry.utils.deepClone(eff.duration), { rounds: rr, seconds: null });
      if (cs) upd["flags.dae.specialDuration"] = [];
      await eff.update(upd);
    }
    const fireOpts = targetUuids ? { midiOptions: { targetUuids } } : {};
    if (targetUuids) {
      const tks = targetUuids.map(u => fromUuidSync(u)?.object).filter(Boolean);
      if (tks.length) setTargets(tks);
    }
    let wf = null, capturedTargets = [];
    try {
      wf = await fire(aid, fireOpts);
      capturedTargets = [...(game.user?.targets ?? [])];   // 在 finally 清目标前先抓一份
    } finally {
      if (backup) await eff.update({ changes: backup.changes, duration: backup.duration, "flags.dae.specialDuration": backup.special });
      if (targetUuids) clearTargets();
    }
    // —— 滑音发放已移交 world-scripter 的 RollComplete 钩子（GM 端、目标可靠）——
    // 这里不再在宏内发放，避免目标抓不到/秒删等问题。
  }
  const playAlly  = (k, improv = false) => play("al", k, { improv });
  const playEnemy = (k, improv = false) => play("en", k, { improv });

  // 侦测场上带有本琴音符的目标（续奏只能续已奏出的轮型音符）
  function detectActiveNotes() {
    const hits = [];
    const allKeys = { al: Object.keys(IDS.al), en: Object.keys(IDS.en) };
    const nameOf = (side, k) => NOTES[side][k].name;
    const roundOf = (side, k) => {
      const eid = (side === "al" ? IDS.aleff : IDS.eneff)[k];
      return (theItem.effects.get(eid)?.flags?.dae?.specialDuration ?? []).includes("turnEnd");
    };
    for (const t of canvas.tokens.placeables) {
      const a = t.actor; if (!a) continue;
      for (const e of (a.appliedEffects ?? a.effects ?? [])) {
        for (const side of ["al", "en"]) for (const k of allKeys[side]) {
          if (e.name === nameOf(side, k))
            hits.push({ tokenId: t.id, uuid: t.document.uuid, tname: t.name, side, key: k, round: roundOf(side, k) });
        }
      }
    }
    return hits;
  }

  // —— 动画 + 音效（运行时查库，命中哪个用哪个；全程沙箱）——
  const seqHas = (p) => { try { return !!Sequencer?.Database?.getEntry?.(p, { softFail: true }); } catch (e) { return false; } };
  const firstFx = (arr) => arr.find(seqHas);
  function playSound() {
    // 4 个小提琴音随机（blfx-assets-pack01 的 Sequencer 数据库条目）
    try {
      if (typeof Sequencer !== "undefined") {
        const n = 1 + Math.floor(Math.random() * 4);
        const key = `blfx.sound.misc.musical_instruments.violin.${n}`;
        if (Sequencer?.Database?.getEntry?.(key, { softFail: true })) {
          new Sequence().sound().file(key).volume(0.6).play();
          return;
        }
      }
    } catch (e) {}
    // 兜底：Foundry 自带
    for (const src of ["sounds/notify.wav", "sounds/drums.wav"]) {
      try { foundry.audio.AudioHelper.play({ src, volume: 0.4, autoplay: true, loop: false }, false); return; } catch (e) {}
    }
  }
  function animate(label, targetTokens = []) {
    try {
      const me = actor.getActiveTokens()[0];
      if (me && canvas?.interface?.createScrollingText)
        canvas.interface.createScrollingText(me.center, "♪ " + label + " ♪",
          { fontSize: 32, fill: "#d4a93a", stroke: "#3a2c12", strokeThickness: 4, duration: 2000, anchor: 2, direction: 1 });
      playSound();
      if (typeof Sequencer === "undefined" || !me) return;
      const castFx = firstFx(["jb2a.energy_strands.complete.purple.01", "jb2a.energy_strands.range.standard.purple.01",
        "jb2a.magic_signs.rune.enchantment.intro.purple", "jb2a.cast_generic.psychic.01.purple.0", "jb2a.dancing_light.purple"]);
      const beamFx = firstFx(["jb2a.energy_beam.normal.bluepink.30ft", "jb2a.energy_beam.normal.purple.30ft",
        "jb2a.lightning_strike.blue.0", "jb2a.bardic_inspiration.purple"]);
      const hitFx = firstFx(["jb2a.markers.music.purple", "jb2a.energy_strands.in.purple.01",
        "jb2a.dancing_light.purple", "jb2a.sphere_of_annihilation.150px.purple"]);
      const seq = new Sequence();
      if (castFx) seq.effect().atLocation(me).file(castFx).scaleToObject(2).fadeOut(500).belowTokens();
      for (const t of targetTokens) {
        if (!t) continue;
        if (beamFx) seq.effect().atLocation(me).stretchTo(t).file(beamFx).fadeOut(300);
        if (hitFx)  seq.effect().atLocation(t).file(hitFx).scaleToObject(1.6).fadeOut(400).delay(150);
      }
      seq.play();
    } catch (e) { console.warn("知音 animate:", e); }
  }
  // 临时画一个范围圈（纯参照，自动消失，不触发选目标）
  async function flashRange(centerToken, feet, secs = 2.5) {
    try {
      const c = centerToken?.center; if (!c) return;
      const tmpl = await canvas.scene.createEmbeddedDocuments("MeasuredTemplate", [{
        t: "circle", user: game.user.id, x: c.x, y: c.y, distance: feet,
        direction: 0, fillColor: "#c9b070", borderColor: "#7a5c2e",
        flags: { zhiyin: { ephemeral: true } }
      }]);
      const id = tmpl?.[0]?.id;
      if (id) setTimeout(() => { try { canvas.scene.deleteEmbeddedDocuments("MeasuredTemplate", [id]); } catch (e) {} }, secs * 1000);
    } catch (e) { console.warn("知音 flashRange:", e); }
  }
  async function chatCard(title, rows) {
    const body = rows.map(([t,d]) => `<p style="margin:.25em 0"><b style="color:#7a5c2e">${t}</b>：${d}</p>`).join("");
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor }),
      content: `<div style="border-left:3px solid #c9b070;padding-left:8px">
        <p style="margin:.1em 0 .35em"><b>🎻 ${title}</b></p>${body}</div>`
    });
  }

  globalThis.__zhiyinPanelOpen = true;
  injectCSS();
  try {
    while (true) {
      const it = findInsp();
      const head = it ? `当前激励：${it.name}（${inspRemaining(it)}）` : "未绑定激励骰";
      const mode = await DV2.wait({
        ...DLG, window: { title: "🎻 演奏知音 · 和鸣", resizable: true },
        content: `<p style="margin:.1em 0 .5em">${head}　|　一拍双弦/即兴 耗1，齐奏 耗2，续奏/安魂曲 不耗</p>`,
        buttons: [
          { action:"duet",    label:"一拍双弦" },
          { action:"improv",  label:"即兴（随机·各强一档）" },
          { action:"tutti",   label:"齐奏（盟友音符及全盟友）" },
          { action:"carry",   label:"续奏（免费再奏）" },
          { action:"requiem", label:"最后的安魂曲" },
          { action:"bind",    label:"⚙ 绑定激励骰" },
          { action:"overdraft", label:"⚙ 透支借音（叠失谐·债）" },
        ], rejectClose: false
      });
      if (!mode) break;
      if (mode === "bind") { await bindInspiration(); continue; }
      if (mode === "overdraft") { await overdraft(); continue; }

      if (mode === "duet") {
        const r = await DV2.wait({
          ...DLG, window:{ title:"一拍双弦 · 选择和弦", resizable:true },
          content:`<div style="display:grid;gap:.6em;min-width:460px">
            <label>盟友弦：<br><select name="al" style="width:100%">${opt(AL_KEYS,"al")}</select></label>
            <label>敌弦：<br><select name="en" style="width:100%">${opt(EN_KEYS,"en")}</select></label></div>`,
          buttons:[{action:"ok",label:"奏响",default:true,callback:(e,b)=>({al:b.form.elements.al.value,en:b.form.elements.en.value})},
                   {action:"cancel",label:"返回"}], rejectClose:false
        });
        if (!r || r==="cancel") continue;
        if (!await spend(1)) continue;
        const wfA = await playAlly(r.al); const wfE = await playEnemy(r.en);
        animate(nm("al",r.al)+" / "+nm("en",r.en), [...(wfA?.targets||[]), ...(wfE?.targets||[])]);
        await chatCard("一拍双弦", [["盟友弦 "+nm("al",r.al), ofc("al",r.al)],["敌弦 "+nm("en",r.en), ofc("en",r.en)]]);
        break;
      }
      else if (mode === "improv") {
        if (!await spend(1)) continue;
        const al=rand(AL_KEYS), en=rand(EN_KEYS);
        const wfA = await playAlly(al,true); const wfE = await playEnemy(en,true);
        animate("即兴 "+nm("al",al)+" / "+nm("en",en), [...(wfA?.targets||[]), ...(wfE?.targets||[])]);
        await chatCard("即兴（各强一档：数值额外+"+chamod+"；单次型保持下一次、轮型+1轮）",
          [["盟友弦 "+nm("al",al), ofc("al",al)],["敌弦 "+nm("en",en), ofc("en",en)]]);
        break;
      }
      else if (mode === "tutti") {
        const r = await DV2.wait({
          ...DLG, window:{ title:"齐奏 · 选择盟友音符", resizable:true },
          content:`<label>盟友弦（及于 30 尺内所有盟友）：<br><select name="al" style="width:100%;min-width:440px">${opt(AL_KEYS,"al")}</select></label>`,
          buttons:[{action:"ok",label:"奏响",default:true,callback:(e,b)=>b.form.elements.al.value},{action:"cancel",label:"返回"}], rejectClose:false
        });
        if (!r || r==="cancel") continue;
        if (!await spend(2)) continue;
        const me = actor.getActiveTokens()[0];
        const allies = canvas.tokens.placeables.filter(t => t.actor && t.id!==me?.id &&
          t.document.disposition === me?.document.disposition &&
          canvas.grid.measurePath([me.center, t.center]).distance <= 30);
        if (!allies.length) { ui.notifications.warn("知音：30尺内无其他盟友。"); continue; }
        for (const a of allies) await fire(IDS.al[r], { midiOptions:{ targetUuids:[a.document.uuid] } });
        animate("齐奏 "+nm("al",r), allies);
        await chatCard("齐奏 Tutti（30尺内全盟友）", [[nm("al",r), ofc("al",r)]]);
        break;
      }
      else if (mode === "carry") {
        const hits = detectActiveNotes().filter(h => h.round);   // 只续"持续到你下回合"的轮型音符
        if (!hits.length) { ui.notifications.warn("知音：场上没有可延长的轮型音符（单次型如协奏/走音是'下一次'，不可续）。先奏一个持续型音符吧。"); continue; }
        const optHits = hits.map((h, i) =>
          `<option value="${i}">${h.tname} ← ${nm(h.side, h.key)}（${h.side === "al" ? "盟友弦" : "敌弦"}）</option>`).join("");
        const r = await DV2.wait({
          ...DLG, window:{ title:"续奏 · 延长一个持续型音符", resizable:true },
          content:`<p style="margin:.1em 0 .5em">续奏会把所选音符的持续延长到 2 轮（仅限"持续到你下回合"的轮型音符；单次型不在此列）。</p>
            <select name="h" style="width:100%;min-width:440px">${optHits}</select>`,
          buttons:[{action:"ok",label:"续奏",default:true,callback:(e,b)=>b.form.elements.h.value},{action:"cancel",label:"返回"}],
          rejectClose:false
        });
        if (!r || r==="cancel") continue;
        const h = hits[Number(r)];
        // 轮型延长到 2 轮：清掉 turnEnd（否则到目标回合末就移除），改用 2 轮计时。定向到该目标。
        await play(h.side, h.key, { rounds: 2, clearSpecial: true, targetUuids: [h.uuid] });
        animate("续奏 "+nm(h.side,h.key), [canvas.tokens.get(h.tokenId)].filter(Boolean));
        await chatCard("续奏 Carry（"+h.tname+" 身上的音符延长到 2 轮）", [[nm(h.side,h.key), ofc(h.side,h.key)]]);
        break;
      }
      else if (mode === "requiem") {
        const me = actor.getActiveTokens()[0];
        const within = canvas.tokens.placeables.filter(t => t.actor && me &&
          canvas.grid.measurePath([me.center, t.center]).distance <= 30);
        const enemies = within.filter(t => t.id!==me.id && t.document.disposition !== me.document.disposition);
        const allies  = within.filter(t => t.document.disposition === me.document.disposition); // 含自己
        await flashRange(me, 30, 3);   // 画一个 30 尺参照圈，3 秒后自动消失
        animate("最后的安魂曲", within);
        if (enemies.length) { setTargets(enemies);
          await fire(IDS.req_en, { midiOptions:{ targetUuids: enemies.map(t=>t.document.uuid) } }); }
        if (allies.length) { setTargets(allies);
          await fire(IDS.req_al, { midiOptions:{ targetUuids: allies.map(t=>t.document.uuid) } }); }
        clearTargets();
        await chatCard("最后的安魂曲 The Last Requiem (30尺)",
          [["敌方", NOTES.req.en],["你与盟友", NOTES.req.al]]);
        break;
      }
    }
  } finally {
    globalThis.__zhiyinPanelOpen = false;
    removeCSS();
  }
})();

